TypeScript example:

const hook = createDeferredHook({
  onEvent: (type, payload, meta) => {
    if (type === 'partial') console.log('chunk:', payload.text);
    if (type === 'result') handleFinal(payload);
  }
});

// call into runtime; returns a Promise that resolves when final event received
await client.invokeTool('search-db', {query}, hook);

// legacy shim usage:
const wrapped = mapLegacyHandler(oldHandler);
await client.invokeTool('search-db', {query}, wrapped);

Python example:

from redwood_sdk import DeferredHook, client

class MyHook(DeferredHook):
    def on_event(self, etype: str, payload, meta=None):
        if etype == 'partial':
            print(payload.get('text', ''))
        elif etype == 'result':
            process_final(payload)

hook = MyHook()
await client.invoke_tool('search-db', {'query': q}, hook)

# adapter for legacy sync handler
wrapped = map_legacy_handler(sync_handler)
await client.invoke_tool('search-db', {'query': q}, wrapped)

Go example:

type HookFunc func(eventType string, payload map[string]interface{}, meta map[string]interface{})

hook := NewDeferredHook(func(t string, p map[string]interface{}, m map[string]interface{}) {
  switch t {
  case "partial": fmt.Println(p["text"])
  case "result": handleFinal(p)
  }
})

client.InvokeTool(context.Background(), "search-db", params, hook)

// legacy adapter
wrapped := MapLegacyHandler(oldHandler)
client.InvokeTool(context.Background(), "search-db", params, wrapped)
